def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    if len(pts)>=2:
        (r1,c1),(r2,c2)=pts[-2:]
        dr,dc=r2-r1,c2-c1
        r,c=r2+dr,c2+dc
        while c<w and r>=0:
            while r>=len(out): out.append([9]*w)
            out[r][c]=1
            r+=dr; c+=dc
    return out
